            </div>

          </div>
        </div>
      </section>

      {/* Modal / Lightbox */}
      {selectedImageIndex !== null && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center bg-black/95 backdrop-blur-sm animate-fade-in">
          <button 
