                 {JSONBIN_BIN_ID === "REPLACE_WITH_YOUR_BIN_ID" && (
                    <span className="bg-red-100 text-red-600 px-3 py-1 rounded-full text-sm font-bold flex items-center gap-2">
                        <Lock size={14} /> DB Not Configured
                    </span>
                 )}
                <button onClick={() => setIsAuthenticated(false)} className="text-red-600 font-bold hover:underline">Logout</button>
            </div>
        </div>

        {/* Tabs */}
        <div className="flex gap-2 md:gap-4 mb-8 overflow-x-auto pb-2">
            {[
                {id: 'comments', label: 'Comments'}, 
                {id: 'packages', label: 'Packages'}, 
                {id: 'history', label: 'History'},
                {id: 'settings', label: 'Settings', icon: <Settings size={18}/>}
            ].map(tab => (
                <button
                    key={tab.id}
                    onClick={() => setActiveTab(tab.id as any)}
                    className={`px-4 md:px-6 py-2 rounded-full font-bold capitalize whitespace-nowrap transition flex items-center gap-2 ${activeTab === tab.id ? 'bg-brand-600 text-white shadow-md' : 'bg-white text-gray-600 hover:bg-gray-100'}`}
                >
                    {tab.icon} {tab.label}
                </button>
            ))}
        </div>

        {/* --- SETTINGS TAB --- */}
        {activeTab === 'settings' && (
            <div className="bg-white rounded-2xl shadow p-6 md:p-8 space-y-8">
                <div>
                    <h2 className="text-2xl font-bold mb-4 flex items-center gap-2">
                        <Database className="text-brand-600" /> Database Configuration
                    </h2>
                    <p className="text-gray-600 mb-6">
                        To save your website data (Packages, History, Comments) permanently, you need a <strong>Bin ID</strong> from Jsonbin.io.
                    </p>
                </div>

                {/* Step 1 */}
                <div className="bg-gray-50 p-6 rounded-xl border border-gray-200">
                    <h3 className="font-bold text-lg mb-3">Step 1: Enter API Key</h3>
                    <p className="text-sm text-gray-500 mb-4">Get your Master Key from <a href="https://jsonbin.io/app/api-keys" target="_blank" className="text-blue-600 hover:underline">Jsonbin.io API Keys</a>.</p>
                    <input 
                        type="text" 
                        value={apiKey} 
                        onChange={(e) => setApiKey(e.target.value)}
                        placeholder="e.g. $2a$10$..." 
                        className="w-full border p-3 rounded-lg font-mono text-sm"
                    />
                </div>

                {/* Step 2 */}
                <div className="bg-gray-50 p-6 rounded-xl border border-gray-200">
                    <h3 className="font-bold text-lg mb-3">Step 2: Create Database Bin</h3>
                    <p className="text-sm text-gray-500 mb-4">This will create a new storage container for your website data.</p>
                    <button 
                        onClick={handleCreateBin} 
                        disabled={isCreatingBin}
                        className="bg-brand-600 text-white px-6 py-3 rounded-lg font-bold hover:bg-brand-700 transition flex items-center gap-2 disabled:opacity-50"
                    >
                        {isCreatingBin ? 'Creating...' : 'Create Database Bin'}
                    </button>
                </div>

                {/* Step 3 */}
                {generatedBinId && (
                    <div className="bg-green-50 p-6 rounded-xl border border-green-200 animate-fade-in-up">
                        <h3 className="font-bold text-lg mb-3 text-green-800 flex items-center gap-2">
                            <Check className="bg-green-200 rounded-full p-1" /> Bin Created Successfully!
                        </h3>
                        <p className="text-sm text-green-700 mb-4">
                            Copy this ID and replace <code>JSONBIN_BIN_ID</code> in your <code>src/constants.ts</code> file.
                        </p>

                        <div className="flex gap-2">
                            <code className="flex-grow bg-white border border-green-200 p-3 rounded-lg font-mono text-green-900 font-bold">
                                {generatedBinId}
                            </code>
                            <button onClick={() => copyToClipboard(generatedBinId)} className="bg-green-600 text-white px-4 rounded-lg hover:bg-green-700">
                                <Copy size={20} />
                            </button>
                        </div>
                    </div>
                )}
            </div>
        )}

        {/* --- COMMENTS TAB --- */}
        {activeTab === 'comments' && (
            <div className="bg-white rounded-2xl shadow p-6">
                <div className="flex justify-between mb-6">
                    <h2 className="text-xl font-bold">Manage Comments ({comments.length})</h2>
                </div>
                <div className="space-y-4">
                    {comments.map(c => (
                        <div key={c.id} className="border p-4 rounded-lg flex justify-between items-start hover:bg-gray-50">
                            <div>
                                <div className="flex items-center gap-2 mb-1">
                                    <span className="font-bold">{c.name}</span>
                                    <span className="text-xs text-gray-400">{c.date}</span>
                                    <span className="text-xs bg-yellow-100 text-yellow-700 px-2 rounded-full">★ {c.rating}</span>
                                </div>
                                <p className="text-gray-600 text-sm">{c.text}</p>
                            </div>
                            <button onClick={() => {if(window.confirm('Delete?')) deleteComment(c.id)}} className="text-red-500 hover:bg-red-50 p-2 rounded">
                                <Trash2 size={18} />
                            </button>
                        </div>
                    ))}
                    {comments.length === 0 && <p className="text-gray-400 text-center py-4">No comments yet.</p>}
                </div>
            </div>
        )}

        {/* --- PACKAGES TAB --- */}
        {activeTab === 'packages' && (
            <div className="space-y-6">
                <div className="flex justify-between items-center">
                    <h2 className="text-xl font-bold">Current Packages ({packages.length})</h2>
                    <button onClick={() => setShowPackageForm(true)} className="bg-brand-600 text-white px-4 py-2 rounded-lg flex items-center gap-2 font-bold hover:bg-brand-700">
                        <Plus size={18} /> Add Package
                    </button>
                </div>

                {showPackageForm && (
                    <div className="bg-white p-6 rounded-2xl shadow-xl border-2 border-brand-100">
                        <h3 className="font-bold text-lg mb-4">Add New Package</h3>
                        <form onSubmit={handleAddPackage} className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            <input required placeholder="Title (English)" className="border p-2 rounded" value={newPkg.titleEn} onChange={e => setNewPkg({...newPkg, titleEn: e.target.value})} />
                            <input required placeholder="Title (Urdu)" className="border p-2 rounded text-right" value={newPkg.titleUr} onChange={e => setNewPkg({...newPkg, titleUr: e.target.value})} />

                            <input required placeholder="Location (English)" className="border p-2 rounded" value={newPkg.locationEn} onChange={e => setNewPkg({...newPkg, locationEn: e.target.value})} />
                            <input required placeholder="Location (Urdu)" className="border p-2 rounded text-right" value={newPkg.locationUr} onChange={e => setNewPkg({...newPkg, locationUr: e.target.value})} />

                            <input required placeholder="Price (e.g., PKR 50,000)" className="border p-2 rounded" value={newPkg.price} onChange={e => setNewPkg({...newPkg, price: e.target.value})} />
                            <input required placeholder="Duration (e.g., 5 Days)" className="border p-2 rounded" value={newPkg.durationEn} onChange={e => setNewPkg({...newPkg, durationEn: e.target.value})} />
                            <input required placeholder="Duration Urdu" className="border p-2 rounded text-right" value={newPkg.durationUr} onChange={e => setNewPkg({...newPkg, durationUr: e.target.value})} />

                            <input placeholder="Date/Availability (e.g. Every Monday)" className="border p-2 rounded" value={newPkg.dates} onChange={e => setNewPkg({...newPkg, dates: e.target.value})} />

                            <div className="md:col-span-2">
                                <input required placeholder="Image URL" className="border p-2 rounded w-full" value={newPkg.image} onChange={e => setNewPkg({...newPkg, image: e.target.value})} />
                                <p className="text-xs text-gray-400 mt-1">Paste a URL from the web.</p>
                            </div>

                            <textarea required placeholder="Description (English)" className="border p-2 rounded md:col-span-2" rows={3} value={newPkg.descriptionEn} onChange={e => setNewPkg({...newPkg, descriptionEn: e.target.value})} />
                            <textarea required placeholder="Description (Urdu)" className="border p-2 rounded md:col-span-2 text-right" rows={3} value={newPkg.descriptionUr} onChange={e => setNewPkg({...newPkg, descriptionUr: e.target.value})} />

                            <textarea placeholder="Itinerary (One item per line)" className="border p-2 rounded md:col-span-2" rows={4} onChange={e => setNewPkg({...newPkg, itineraryEn: e.target.value as any})} />
                            <textarea placeholder="Inclusions (One item per line)" className="border p-2 rounded md:col-span-2" rows={4} onChange={e => setNewPkg({...newPkg, inclusionsEn: e.target.value as any})} />

                            <div className="md:col-span-2 flex gap-2 justify-end">
                                <button type="button" onClick={() => setShowPackageForm(false)} className="px-4 py-2 text-gray-600">Cancel</button>
                                <button type="submit" className="bg-brand-600 text-white px-6 py-2 rounded-lg font-bold">Save Package</button>
                            </div>
                        </form>
                    </div>
                )}

                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                    {packages.map(pkg => (
                        <div key={pkg.id} className="bg-white border rounded-xl overflow-hidden shadow-sm relative group">
                            <img src={pkg.image} className="h-40 w-full object-cover" />
                            <div className="p-4">
                                <h3 className="font-bold">{pkg.titleEn}</h3>
                                <p className="text-sm text-gray-500">{pkg.price} • {pkg.durationEn}</p>
                                <p className="text-xs text-brand-600 font-bold mt-1">{pkg.dates}</p>
                            </div>
                            <button onClick={() => {if(window.confirm('Delete?')) deletePackage(pkg.id)}} className="absolute top-2 right-2 bg-red-600 text-white p-2 rounded-full opacity-0 group-hover:opacity-100 transition">
                                <Trash2 size={16} />
                            </button>
                        </div>
                    ))}
                </div>
            </div>
        )}

        {/* --- HISTORY TAB --- */}
        {activeTab === 'history' && (
            <div className="space-y-6">
                <div className="flex justify-between items-center">
                    <h2 className="text-xl font-bold">Travel History ({history.length})</h2>
                    <button onClick={() => setShowHistoryForm(true)} className="bg-brand-600 text-white px-4 py-2 rounded-lg flex items-center gap-2 font-bold hover:bg-brand-700">
                        <Plus size={18} /> Add History
                    </button>
                </div>

                {showHistoryForm && (
                    <div className="bg-white p-6 rounded-2xl shadow-xl border-2 border-brand-100">
                        <h3 className="font-bold text-lg mb-4">Add Travel Event</h3>
                        <form onSubmit={handleAddHistory} className="space-y-4">
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                <input required placeholder="Trip Title (e.g., Winter Tour 2024)" className="border p-2 rounded" value={newHistory.title} onChange={e => setNewHistory({...newHistory, title: e.target.value})} />
                                <input required placeholder="Date (e.g., Dec 2023)" className="border p-2 rounded" value={newHistory.date} onChange={e => setNewHistory({...newHistory, date: e.target.value})} />
                                <input required placeholder="Location" className="border p-2 rounded" value={newHistory.location} onChange={e => setNewHistory({...newHistory, location: e.target.value})} />
                                <input required placeholder="Main Image URL" className="border p-2 rounded" value={newHistory.images?.[0]} onChange={e => setNewHistory({...newHistory, images: [e.target.value]})} />
                            </div>
                            <textarea required placeholder="Description of the trip..." className="border p-2 rounded w-full" rows={3} value={newHistory.description} onChange={e => setNewHistory({...newHistory, description: e.target.value})} />

                            {/* Visitor Adder */}
                            <div className="bg-gray-50 p-4 rounded-xl">
                                <h4 className="font-bold text-sm mb-2">Add Visitors</h4>
                                <div className="flex gap-2 mb-2">
                                    <input placeholder="Visitor Name" className="border p-2 rounded flex-1" value={visitorInput.name} onChange={e => setVisitorInput({...visitorInput, name: e.target.value})} />
                                    <input placeholder="Details (e.g. City)" className="border p-2 rounded flex-1" value={visitorInput.details} onChange={e => setVisitorInput({...visitorInput, details: e.target.value})} />
                                    <button type="button" onClick={handleAddVisitor} className="bg-black text-white px-4 rounded font-bold">Add</button>
                                </div>
                                <div className="flex flex-wrap gap-2">
                                    {newHistory.visitors?.map((v, idx) => (
                                        <span key={idx} className="bg-white border px-3 py-1 rounded-full text-sm flex items-center gap-2">
                                            {v.name} <span className="text-gray-400">({v.details})</span>
                                        </span>
                                    ))}
                                </div>
                            </div>

                            <div className="flex gap-2 justify-end">
                                <button type="button" onClick={() => setShowHistoryForm(false)} className="px-4 py-2 text-gray-600">Cancel</button>
                                <button type="submit" className="bg-brand-600 text-white px-6 py-2 rounded-lg font-bold">Save History</button>
                            </div>
                        </form>
                    </div>
                )}

                <div className="space-y-4">
                    {history.map(item => (
                        <div key={item.id} className="bg-white border rounded-xl p-6 shadow-sm flex flex-col md:flex-row gap-6 relative group">
                             <img src={item.images[0]} className="w-full md:w-48 h-32 object-cover rounded-lg" />
                             <div className="flex-grow">
                                 <div className="flex justify-between items-start">
                                     <h3 className="font-bold text-xl">{item.title}</h3>
                                     <span className="text-sm bg-gray-100 px-3 py-1 rounded-full">{item.date}</span>
                                 </div>
                                 <p className="text-brand-600 text-sm mb-2">{item.location}</p>
                                 <p className="text-gray-600 mb-4">{item.description}</p>
                                 <div className="flex items-center gap-2 text-sm text-gray-500">
                                     <Users size={16} /> {item.visitors.length} Visitors
                                 </div>
                             </div>
                             <button onClick={() => {if(window.confirm('Delete?')) deleteHistory(item.id)}} className="absolute top-4 right-4 bg-red-100 text-red-600 p-2 rounded hover:bg-red-200 transition">
                                <Trash2 size={20} />
                             </button>
                        </div>
                    ))}
                </div>
            </div>
        )}

      </div>
    </div>
  );
};

export default Admin;

import React, { useState, useEffect, useRef } from 'react';
import { Send, MessageSquare, Clock, Star, Loader2, AlertCircle, ArrowDown } from 'lucide-react';
import { CONTENT, JSONBIN_BIN_ID } from '../constants';
import { Language, Comment } from '../types';
import { useData } from '../context/DataContext';

interface CommentsSectionProps {
  lang: Language;
}

const COLORS = [
  'bg-red-500', 'bg-blue-500', 'bg-green-500', 
  'bg-yellow-500', 'bg-purple-500', 'bg-pink-500', 
  'bg-indigo-500', 'bg-teal-500'
];

const CommentsSection: React.FC<CommentsSectionProps> = ({ lang }) => {
  const t = CONTENT[lang].commentsSection;
  const isUrdu = lang === 'ur';

  // Use Context
  const { comments, addComment } = useData();

  const [name, setName] = useState('');
  const [text, setText] = useState('');
  const [rating, setRating] = useState(5);
  const [hoverRating, setHoverRating] = useState(0);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [showNotification, setShowNotification] = useState(false);
  const prevCommentsLength = useRef(comments.length);
  const commentsListRef = useRef<HTMLDivElement>(null);

  // Check for new comments (polling handled by Context, we just react to prop change)
  useEffect(() => {
    if (comments.length > prevCommentsLength.current && prevCommentsLength.current !== 0) {
        setShowNotification(true);
    }
    prevCommentsLength.current = comments.length;
  }, [comments]);

  const handleScrollToComments = () => {
    commentsListRef.current?.scrollIntoView({ behavior: 'smooth', block: 'center' });
    setShowNotification(false);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!name.trim() || !text.trim()) return;

    setIsSubmitting(true);

    const newComment: Comment = {
      id: Date.now(),
      name: name,
      text: text,
      date: new Date().toLocaleDateString(),
      avatarColor: COLORS[Math.floor(Math.random() * COLORS.length)],
      rating: rating
    };

    await addComment(newComment);

    setName('');
    setText('');
    setRating(5);
    setIsSubmitting(false);
  };

  // Cast to string to prevent TS error about comparison with literal type
  const isConfigured = (JSONBIN_BIN_ID as string) !== "REPLACE_WITH_YOUR_BIN_ID";

  return (
    <section className="py-12 md:py-20 bg-white relative">
      {/* New Comments Notification */}
      {showNotification && (
        <button 
            onClick={handleScrollToComments}
            className="fixed top-24 left-1/2 transform -translate-x-1/2 z-50 bg-brand-600 text-white px-6 py-3 rounded-full shadow-2xl flex items-center gap-2 animate-bounce hover:bg-brand-700 transition-colors cursor-pointer border-2 border-white ring-2 ring-brand-200"
        >
            <MessageSquare size={20} fill="currentColor" className="text-white" />
            <span className="font-bold whitespace-nowrap">New Comments</span>
            <ArrowDown size={20} />
        </button>
      )}

      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">

        <div className="text-center mb-12">
            <h2 className={`text-3xl md:text-4xl font-bold text-brand-900 mb-4 ${isUrdu ? 'font-urdu' : ''}`}>
                {t.title}
            </h2>
            <p className={`text-gray-500 ${isUrdu ? 'font-urdu' : ''}`}>
                {t.subtitle}
            </p>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 lg:gap-12">

            {/* Comment Form */}
            <div className={`lg:col-span-1 bg-brand-50 p-6 md:p-8 rounded-2xl shadow-lg border border-brand-100 h-fit ${isUrdu ? 'lg:order-last' : ''}`}>
                <h3 className={`text-xl font-bold text-brand-800 mb-6 flex items-center gap-2 ${isUrdu ? 'flex-row-reverse font-urdu' : ''}`}>
                    <MessageSquare className="text-brand-500" />
                    {t.submitBtn}
                </h3>

                {!isConfigured && (
                  <div className="mb-4 p-3 bg-yellow-50 border border-yellow-200 rounded-lg text-yellow-800 text-xs">
                    <p className="font-bold flex items-center gap-1"><AlertCircle size={14}/> Setup Required</p>
                    <p>Go to Admin Portal &gt; Settings to create your Bin ID.</p>
                  </div>
                )}

                <form onSubmit={handleSubmit} className="space-y-4">
                    <div>
                        <input 
                            type="text" 
                            placeholder={t.namePlaceholder}
                            value={name}
                            onChange={(e) => setName(e.target.value)}
                            disabled={isSubmitting}
                            className={`w-full px-4 py-3 rounded-xl border border-gray-200 focus:ring-2 focus:ring-brand-500 outline-none transition disabled:opacity-50 ${isUrdu ? 'text-right font-urdu' : ''}`}
                            required
                        />
                    </div>

                    {/* Star Rating Input */}
                    <div className={`flex flex-col gap-2 ${isUrdu ? 'items-end' : 'items-start'}`}>
                        <span className={`text-sm text-gray-500 font-medium ${isUrdu ? 'font-urdu' : ''}`}>
                            {isUrdu ? 'درجہ بندی:' : 'Rating:'}
                        </span>
                        <div className={`flex items-center gap-1 ${isUrdu ? 'flex-row-reverse' : ''}`}>
                            {[1, 2, 3, 4, 5].map((star) => (
                                <button
                                    key={star}
                                    type="button"
                                    onClick={() => setRating(star)}
                                    onMouseEnter={() => setHoverRating(star)}
                                    onMouseLeave={() => setHoverRating(0)}
                                    disabled={isSubmitting}
                                    className="focus:outline-none transition-transform hover:scale-110 disabled:cursor-not-allowed"
                                >
                                    <Star 
                                        size={24} 
                                        className={`${(hoverRating || rating) >= star ? 'text-amber-400 fill-amber-400' : 'text-gray-300'}`} 
                                    />
                                </button>
                            ))}
                        </div>
                    </div>

                    <div>
                        <textarea 
                            rows={4}
                            placeholder={t.commentPlaceholder}
                            value={text}
                            onChange={(e) => setText(e.target.value)}
                            disabled={isSubmitting}
                            className={`w-full px-4 py-3 rounded-xl border border-gray-200 focus:ring-2 focus:ring-brand-500 outline-none transition resize-none disabled:opacity-50 ${isUrdu ? 'text-right font-urdu' : ''}`}
                            required
                        ></textarea>
                    </div>

                    <button 
                        type="submit" 
                        disabled={isSubmitting}
                        className={`w-full bg-brand-600 text-white font-bold py-3 rounded-xl shadow-md hover:bg-brand-700 transition flex items-center justify-center gap-2 disabled:opacity-70 disabled:cursor-not-allowed ${isUrdu ? 'flex-row-reverse font-urdu' : ''}`}
                    >
                        {isSubmitting ? (
                          <>Processing...</>
                        ) : (
                          <>
                            {t.submitBtn}
                            <Send size={18} />
                          </>
                        )}
                    </button>
                </form>
            </div>

            {/* Comments List */}
            <div className="lg:col-span-2" ref={commentsListRef}>
                <div className={`flex items-center justify-between mb-6 ${isUrdu ? 'flex-row-reverse' : ''}`}>
                    <h3 className={`text-xl font-bold text-gray-800 ${isUrdu ? 'font-urdu' : ''}`}>
                        {t.recentComments} <span className="text-gray-400 font-normal text-base ml-2">({comments.length})</span>
                    </h3>
                </div>

                <div className="space-y-6 max-h-[600px] overflow-y-auto pr-2 custom-scrollbar">
                    {comments.map((comment) => (
                        <div key={comment.id} className="bg-white p-5 rounded-xl border border-gray-100 shadow-sm hover:shadow-md transition-shadow">
                            <div className={`flex items-start gap-4 ${isUrdu ? 'flex-row-reverse text-right' : ''}`}>
                                <div className={`flex-shrink-0 w-10 h-10 md:w-12 md:h-12 rounded-full ${comment.avatarColor} text-white flex items-center justify-center font-bold text-lg shadow-sm`}>
                                    {comment.name.charAt(0).toUpperCase()}
                                </div>
                                <div className="flex-grow">
                                    <div className={`flex flex-col md:flex-row md:items-center justify-between gap-1 mb-2 ${isUrdu ? 'md:flex-row-reverse' : ''}`}>
                                        <div className="flex flex-col md:flex-row gap-2 items-baseline">
                                            <h4 className="font-bold text-gray-900 text-lg">{comment.name}</h4>
                                            {/* Display Stars in List */}
                                            <div className="flex items-center gap-0.5">
                                                {[...Array(5)].map((_, i) => (
                                                    <Star 
                                                        key={i} 
                                                        size={12} 
                                                        className={i < (comment.rating || 5) ? "text-amber-400 fill-amber-400" : "text-gray-300"} 
                                                    />
                                                ))}
                                            </div>
                                        </div>
                                        <span className={`text-xs text-gray-400 flex items-center gap-1 ${isUrdu ? 'flex-row-reverse' : ''}`}>
                                            <Clock size={12} />
                                            {comment.date}
                                        </span>
                                    </div>
                                    <p className={`text-gray-600 leading-relaxed ${isUrdu ? 'font-urdu' : ''}`}>
                                        {comment.text}
                                    </p>
                                </div>
                            </div>
                        </div>
                    ))}

                    {comments.length === 0 && (
                        <div className="text-center py-10 text-gray-400">
                            <p>No comments yet. Be the first to share your story!</p>
                        </div>
                    )}
                </div>
            </div>

        </div>
      </div>
      <style>{`
        .custom-scrollbar::-webkit-scrollbar {
          width: 6px;
        }
        .custom-scrollbar::-webkit-scrollbar-track {
          background: #f1f1f1;
          border-radius: 10px;
        }
        .custom-scrollbar::-webkit-scrollbar-thumb {
          background: #d1d5db;
          border-radius: 10px;
        }
        .custom-scrollbar::-webkit-scrollbar-thumb:hover {
          background: #9ca3af;
        }
      `}</style>
    </section>
  );
};

export default CommentsSection;

import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { TourPackage, TravelHistoryItem, Comment, CloudData } from '../types';
import { PACKAGES, INITIAL_HISTORY, JSONBIN_BIN_ID, JSONBIN_API_KEY } from '../constants';

interface DataContextType {
  packages: TourPackage[];
  history: TravelHistoryItem[];
  comments: Comment[];
  isLoading: boolean;

  // Actions
  addPackage: (pkg: TourPackage) => Promise<void>;
  deletePackage: (id: string) => Promise<void>;
  addHistory: (item: TravelHistoryItem) => Promise<void>;
  deleteHistory: (id: string) => Promise<void>;
  addComment: (comment: Comment) => Promise<void>;
  deleteComment: (id: number) => Promise<void>;

  // Utility
  refreshData: () => Promise<void>;
}

const DataContext = createContext<DataContextType | undefined>(undefined);

export const DataProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [packages, setPackages] = useState<TourPackage[]>(PACKAGES);
  const [history, setHistory] = useState<TravelHistoryItem[]>(INITIAL_HISTORY);
  const [comments, setComments] = useState<Comment[]>([]);
  const [isLoading, setIsLoading] = useState(false);

  // Cast to string to prevent TS error about comparison with literal types
  const isConfigured = (JSONBIN_BIN_ID as string) !== "REPLACE_WITH_YOUR_BIN_ID" && (JSONBIN_API_KEY as string) !== "REPLACE_WITH_YOUR_API_KEY";

  // Load Data from Cloud
  const fetchData = async () => {
    if (!isConfigured) return;

    // Don't set loading on poll/refresh to avoid UI flicker, only initial could be handled if needed
    // But here we might want to know if it's syncing
    try {
      const response = await fetch(`https://api.jsonbin.io/v3/b/${JSONBIN_BIN_ID}/latest`, {
        headers: { 'X-Master-Key': JSONBIN_API_KEY }
      });

      if (response.ok) {
        const data = await response.json();
        const record = data.record;

        // Check if it's the new structure (CloudData) or legacy (Array of comments)
        if (Array.isArray(record)) {
             // Legacy mode: It's just comments
             setComments(record);
             // Keep packages/history as defaults
        } else if (record.packages || record.history) {
             // New CloudData structure
             if (record.packages) setPackages(record.packages);
             if (record.history) setHistory(record.history);
             if (record.comments) setComments(record.comments);
        }
      }
    } catch (error) {
      console.error("Failed to fetch data:", error);
    }
  };

  // Initial Load & Poll
  useEffect(() => {
    fetchData();
    const interval = setInterval(fetchData, 10000); // Poll every 10s for new comments/updates
    return () => clearInterval(interval);
  }, []);

  // Helper to save everything to cloud
  const saveToCloud = async (newData: CloudData) => {
    if (!isConfigured) {
       // If not configured, just update local state (already done in handlers)
       return;
    }

    try {
      await fetch(`https://api.jsonbin.io/v3/b/${JSONBIN_BIN_ID}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
          'X-Master-Key': JSONBIN_API_KEY
        },
        body: JSON.stringify(newData)
      });
    } catch (error) {
      console.error("Failed to save to cloud:", error);
      alert("Failed to save changes to the server. Please check your internet connection.");
    }
  };

  const addPackage = async (pkg: TourPackage) => {
    const newPackages = [pkg, ...packages];
    setPackages(newPackages);
    await saveToCloud({ packages: newPackages, history, comments });
  };

  const deletePackage = async (id: string) => {
    const newPackages = packages.filter(p => p.id !== id);
    setPackages(newPackages);
    await saveToCloud({ packages: newPackages, history, comments });
  };

  const addHistory = async (item: TravelHistoryItem) => {
    const newHistory = [item, ...history];
    setHistory(newHistory);
    await saveToCloud({ packages, history: newHistory, comments });
  };

  const deleteHistory = async (id: string) => {
    const newHistory = history.filter(h => h.id !== id);
    setHistory(newHistory);
    await saveToCloud({ packages, history: newHistory, comments });
  };

  const addComment = async (comment: Comment) => {
    const newComments = [comment, ...comments];
    setComments(newComments);
    await saveToCloud({ packages, history, comments: newComments });
  };

  const deleteComment = async (id: number) => {
    const newComments = comments.filter(c => c.id !== id);
    setComments(newComments);
    await saveToCloud({ packages, history, comments: newComments });
  };

  return (
    <DataContext.Provider value={{
      packages,
      history,
      comments,
      isLoading,
      addPackage,
      deletePackage,
      addHistory,
      deleteHistory,
      addComment,
      deleteComment,
      refreshData: fetchData
    }}>
      {children}
    </DataContext.Provider>
  );
};

export const useData = () => {
  const context = useContext(DataContext);
  if (context === undefined) {
    throw new Error('useData must be used within a DataProvider');
  }
  return context;
};

