                                to={link.path}
                                onClick={() => setIsOpen(false)}
                                className={`block px-3 py-3 rounded-md text-base font-medium text-gray-700 hover:text-brand-600 hover:bg-gray-50 flex-grow ${isUrdu ? 'text-right font-urdu text-xl' : 'text-left'}`}
                             >
                                 {link.name}
                             </Link>
                             <button
                                 onClick={(e) => {
                                     e.preventDefault();
                                     setMobileSubmenuOpen(mobileSubmenuOpen === link.path ? null : link.path);
                                 }}
                                 className="p-3 text-gray-400 hover:text-brand-600 focus:outline-none"
                             >
                                 <ChevronDown size={20} className={`transform transition-transform duration-200 ${mobileSubmenuOpen === link.path ? 'rotate-180' : ''}`} />
                             </button>
                         </div>
                         <div className={`overflow-hidden transition-all duration-300 ease-in-out ${mobileSubmenuOpen === link.path ? 'max-h-48 opacity-100 mb-2' : 'max-h-0 opacity-0'}`}>
                             <div className={`bg-gray-50 rounded-lg py-1 px-2 ${isUrdu ? 'mr-4' : 'ml-4'}`}>
                                 {link.children.map(child => (
                                     <Link
                                         key={child.path}
                                         to={child.path}
                                         onClick={() => setIsOpen(false)}
                                         className={`block px-3 py-2.5 rounded-md text-sm font-medium text-gray-600 hover:text-brand-600 hover:bg-white transition mb-1 last:mb-0 ${isUrdu ? 'text-right font-urdu text-lg' : 'text-left'}`}
                                     >
                                         {child.name}
                                     </Link>
                                 ))}
                             </div>
                         </div>
                     </div>
                 ) : (
                    <Link
                        to={link.path}
                        onClick={() => setIsOpen(false)}
                        className={`block w-full px-3 py-3 rounded-md text-base font-medium text-gray-700 hover:text-brand-600 hover:bg-gray-50 border-b border-gray-50 last:border-0 ${isUrdu ? 'text-right font-urdu text-xl' : 'text-left'}`}
                    >
                        {link.name}
                    </Link>
                 )}
              </div>
            ))}
            <Link
              to="/contact"
              onClick={() => setIsOpen(false)}
              className={`w-full mt-4 block text-center bg-brand-600 text-white px-3 py-3 rounded-md font-bold shadow-md active:scale-95 transition ${isUrdu ? 'font-urdu' : ''}`}
            >
              {t.bookNow}
            </Link>
          </div>
        </div>
      )}
    </nav>
  );
};

export default Navbar;

import React, { useState, useEffect } from 'react';
import Hero from '../components/Hero';
import CommentsSection from '../components/CommentsSection';
import { Mountain, Users, Camera, Star, Quote, MapPin, Bus, Zap, Moon, Compass, Shield, Wind } from 'lucide-react';
import { Language, Comment } from '../types';
import { CONTENT, GALLERY_IMAGES, TESTIMONIALS, JSONBIN_BIN_ID, JSONBIN_API_KEY } from '../constants';
import { Link } from 'react-router-dom';
import { useData } from '../context/DataContext';

interface HomeProps {
  lang: Language;
}

const Home: React.FC<HomeProps> = ({ lang }) => {
  const t = CONTENT[lang];
  const isUrdu = lang === 'ur';
  const { packages } = useData(); // Use dynamic data
  const [recentComments, setRecentComments] = useState<Comment[]>([]);

  // Fetch comments for the Testimonials section
  useEffect(() => {
    const fetchComments = async () => {
      // Don't fetch if keys are not set
      if ((JSONBIN_BIN_ID as string) === "REPLACE_WITH_YOUR_BIN_ID" || (JSONBIN_API_KEY as string) === "REPLACE_WITH_YOUR_API_KEY") return;

      try {
        const response = await fetch(`https://api.jsonbin.io/v3/b/${JSONBIN_BIN_ID}/latest`, {
          headers: {
            'X-Master-Key': JSONBIN_API_KEY
          }
        });

        if (!response.ok) return; // Silent fail, fall back to static

        const data = await response.json();
        const remoteComments = Array.isArray(data.record) ? data.record : [];
        setRecentComments(remoteComments);
      } catch (err) {
        console.error("Error fetching comments for testimonials:", err);
      }
    };

    fetchComments();
  }, []);

  const features = [
    { icon: <Mountain size={40} />, title: t.features.adventure, color: "bg-blue-100 text-blue-600" },
    { icon: <Camera size={40} />, title: t.features.cultural, color: "bg-amber-100 text-amber-600" },
    { icon: <Users size={40} />, title: t.features.family, color: "bg-green-100 text-green-600" },
  ];

  // Pick top 3 images for grid
  const showcaseImages = GALLERY_IMAGES.slice(0, 3);

