      setShowPackageForm(true);
  };

  const closePackageForm = () => {
      setShowPackageForm(false);
      setEditPkgId(null);
      setNewPkg({});
  };

  // --- HISTORY LOGIC ---
  const handleAddVisitor = () => {
      if(visitorInput.name) {
          setNewHistory(prev => ({
