                                </button>
                                <button onClick={() => {if(window.confirm('Delete?')) deleteHistory(item.id)}} className="bg-red-100 text-red-600 p-2 rounded hover:bg-red-200 transition">
                                    <Trash2 size={20} />
                                </button>
                             </div>
                        </div>
                    ))}
                </div>
            </div>
        )}

      </div>
    </div>
  );
};

