```typescript
import Image from "next/image";
import { Bus, Compass, Zap } from "lucide-react";
import { useState } from "react";

const PartnerLogo = ({ partner }: { partner: any }) => {
  const [imgError, setImgError] = useState(false);

  if (imgError) {
    return (
      <div className={`flex items-center gap-2 ${partner.color}`}>
        {partner.icon}
        <span className="text-lg font-black italic tracking-tighter uppercase">
          {partner.name}
        </span>
      </div>
    );
  }

  if (partner.logo) {
    return (
      <Image
        src={partner.logo}
        alt={partner.name}
        width={30}
        height={30}
        className="filter grayscale hover:grayscale-0 transition-all duration-300"
        onError={() => setImgError(true)}
      />
    );
  }

  return (
    <div className={`flex items-center gap-2 ${partner.color}`}>
      {partner.icon}
      <span className="text-lg font-black italic tracking-tighter uppercase">
        {partner.name}
      </span>
    </div>
  );
};
```

