                <p className="text-gray-700" dir="ltr">+92 302 6834300 / +92 300 8885072</p>
            </div>
          </div>

          <div className="relative">
             <div className="absolute inset-y-0 left-0 flex items-center pl-4 text-gray-400 pointer-events-none">
                <ShieldCheck size={20} />
             </div>
             <input
              type="password"
              value={pin}
              onChange={(e) => setPin(e.target.value)}
              maxLength={7}
              placeholder="Enter 7-Digit PIN"
              className="w-full text-center tracking-[8px] font-bold text-lg px-4 py-4 border-2 border-gray-200 rounded-xl focus:ring-2 focus:ring-brand-500 focus:border-brand-500 outline-none transition"
              required
            />
          </div>

          {error && (
            <p className="text-red-600 text-sm text-center flex items-center justify-center gap-2">
                <AlertTriangle size={16} /> {error}
            </p>
          )}

          <button
            type="submit"
            className="w-full bg-brand-600 text-white font-bold py-4 rounded-xl hover:bg-brand-700 transition-colors shadow-lg transform active:scale-95"
          >
            Enter Website
          </button>

          <p className="text-xs text-gray-500 text-center">
            Please contact the admin to request your personal PIN for access.
          </p>
        </div>
      </form>
    </div>
  );
};

export default PinEntry;

import React, { useState, useEffect } from 'react';
import { HashRouter as Router, Routes, Route, useLocation } from 'react-router-dom';
import Navbar from './components/Navbar';
import Footer from './components/Footer';
import Home from './pages/Home';
import About from './pages/About';
import Packages from './pages/Packages';
import PackageDetails from './pages/PackageDetails';
import Gallery from './pages/Gallery';
import Contact from './pages/Contact';
import Admin from './pages/Admin';
import TravelHistory from './pages/TravelHistory';
import WhatsAppButton from './components/WhatsAppButton';
import AdminButton from './components/AdminButton';
import { Language, VisitorLog } from './types';
import { DataProvider, useData } from './context/DataContext';

// Scroll to top helper
const ScrollToTop = () => {
  const { pathname } = useLocation();
  useEffect(() => {
    window.scrollTo(0, 0);
  }, [pathname]);
  return null;
};

// Visitor Tracker Component
const VisitorTracker = () => {
  const { logVisitor } = useData();

  useEffect(() => {
    const trackVisitor = async () => {
        // Simple session check to avoid logging the same user on every refresh within a session
        if (sessionStorage.getItem('visitor_logged')) return;

        let geoData = null;

        try {
            // Try primary API
            const response = await fetch('https://ipwho.is/');
            const data = await response.json();
            if (data.success) {
                geoData = { city: data.city, country: data.country, ip: data.ip };
            } else {
                throw new Error("Primary IP API failed");
            }
        } catch (error) {
            console.warn("Primary Visitor API failed, trying fallback...", error);
            try {
                // Try fallback API
                const response = await fetch('https://ipapi.co/json/');
                const data = await response.json();
                geoData = { city: data.city, country: data.country_name, ip: data.ip };
            } catch (err2) {
                console.error("All visitor tracking APIs failed", err2);
            }
        }

        if (geoData) {
            const ua = navigator.userAgent;
            let device = "Desktop";
            if (/mobile/i.test(ua)) device = "Mobile";
            else if (/tablet/i.test(ua)) device = "Tablet";

            let browser = "Unknown Browser";
            if(ua.indexOf("Chrome") > -1) browser = "Chrome";
            else if(ua.indexOf("Safari") > -1) browser = "Safari";
            else if(ua.indexOf("Firefox") > -1) browser = "Firefox";

            // OS Detection
            let os = "Unknown OS";
            if (ua.indexOf("Win") !== -1) os = "Windows";
            else if (ua.indexOf("Mac") !== -1) os = "MacOS";
            else if (ua.indexOf("Linux") !== -1) os = "Linux";
            else if (ua.indexOf("Android") !== -1) os = "Android";
            else if (ua.indexOf("like Mac") !== -1) os = "iOS";

            const newLog: VisitorLog = {
                id: Date.now().toString(),
                location: `${geoData.city}, ${geoData.country}`,
                date: new Date().toLocaleDateString(),
                time: new Date().toLocaleTimeString(),
                device: `${device} (${os})`,
                browser: browser,
                ip: geoData.ip
            };

            await logVisitor(newLog);
            sessionStorage.setItem('visitor_logged', 'true');
        }
    };

    trackVisitor();
  }, [logVisitor]);

  return null;
};

const App: React.FC = () => {
  const [lang, setLang] = useState<Language>('en');

  return (
    <DataProvider>
      <VisitorTracker />
      <Router>
        <ScrollToTop />
        <div className={`min-h-screen flex flex-col font-sans text-gray-900 ${lang === 'ur' ? 'font-urdu' : ''}`}>
            <Navbar lang={lang} setLang={setLang} />
            <main className="flex-grow">
            <Routes>
                <Route path="/" element={<Home lang={lang} />} />
                <Route path="/about" element={<About lang={lang} />} />
                <Route path="/packages" element={<Packages lang={lang} />} />
                <Route path="/packages/:id" element={<PackageDetails lang={lang} />} />
                <Route path="/gallery" element={<Gallery lang={lang} />} />
                <Route path="/contact" element={<Contact lang={lang} />} />
                <Route path="/travel-history" element={<TravelHistory lang={lang} />} />
                <Route path="/admin" element={<Admin />} />
            </Routes>
            </main>
            <WhatsAppButton />
            <AdminButton />
            <Footer lang={lang} />
        </div>
      </Router>
    </DataProvider>
  );
};

export default App;
